-- Template family keys (catalog.templateFamilies, active keys only, in display order).
create or replace function public.catalog_template_families()
returns text[]
language sql
immutable
set search_path = ''
as $$
  select array['personal', 'offers']::text[]
$$;
revoke all on function public.catalog_template_families() from public, anon, authenticated;

-- The family of a template key (templates/index.json); null for an unknown key.
create or replace function public.catalog_template_family(p_template_key text)
returns text
language sql
immutable
set search_path = ''
as $$
  select case p_template_key when 'classic' then 'personal' when 'modern' then 'personal' when 'minimal' then 'personal' when 'spotlight' then 'offers' when 'guide' then 'offers' else null end
$$;
revoke all on function public.catalog_template_family(text) from public, anon, authenticated;

