-- Current version of an active privacy notice: {version, hash_<locale>...}; null if unknown or deprecated.
create or replace function public.catalog_privacy_notice(p_key text)
returns jsonb
language sql
immutable
set search_path = ''
as $$
  select case p_key when 'agent_signup' then '{"version":1,"hash_en":"ee10393a0af9f4849f911b09c6850d32805be32f31d9f6a942f96a486bb52713","hash_hi":"43613aba84636a50f5af1e9a3ed326dc2abe564ba54d0b7113b5068337970417"}'::jsonb when 'enquiry_form' then '{"version":1,"hash_en":"62c47ee389319fa4cfd147ba2fd1ea14350e8b9201bedd650334a1823584e6d7","hash_hi":"940db3dec13cabfe503f2394d063bbe8d699fd89669d8169c6511860fff2ad51"}'::jsonb when 'agent_customer_duty' then '{"version":1,"hash_en":"5e9c7827d65d1945e5cb3c9be4a75a9d03c11975f575b206b243f55fb757ab7e","hash_hi":"7e700e72bd669904be6422a05791a6e4b5fc4a45dfcf7aa0c9b2075537120979"}'::jsonb when 'guardian_consent' then '{"version":1,"hash_en":"aa352b833bdd55b21b1aafe6a9432abb88851e410768c8231ef9e40307c0e562","hash_hi":"7a34650541944f056c6f463588f565d7c8ad189f383ed25b4af890260b21a62a"}'::jsonb else null end
$$;
revoke all on function public.catalog_privacy_notice(text) from public, anon, authenticated;

-- Text hash of a released notice version in a locale (every version ever generated); null if unknown.
create or replace function public.catalog_privacy_notice_hash(p_key text, p_version integer, p_locale text)
returns text
language sql
immutable
set search_path = ''
as $$
  select t.h from (values
    ('agent_signup', 1, 'en', 'ee10393a0af9f4849f911b09c6850d32805be32f31d9f6a942f96a486bb52713'),
    ('agent_signup', 1, 'hi', '43613aba84636a50f5af1e9a3ed326dc2abe564ba54d0b7113b5068337970417'),
    ('enquiry_form', 1, 'en', '62c47ee389319fa4cfd147ba2fd1ea14350e8b9201bedd650334a1823584e6d7'),
    ('enquiry_form', 1, 'hi', '940db3dec13cabfe503f2394d063bbe8d699fd89669d8169c6511860fff2ad51'),
    ('agent_customer_duty', 1, 'en', '5e9c7827d65d1945e5cb3c9be4a75a9d03c11975f575b206b243f55fb757ab7e'),
    ('agent_customer_duty', 1, 'hi', '7e700e72bd669904be6422a05791a6e4b5fc4a45dfcf7aa0c9b2075537120979'),
    ('guardian_consent', 1, 'en', 'aa352b833bdd55b21b1aafe6a9432abb88851e410768c8231ef9e40307c0e562'),
    ('guardian_consent', 1, 'hi', '7a34650541944f056c6f463588f565d7c8ad189f383ed25b4af890260b21a62a')
  ) as t(k, v, l, h)
  where t.k = p_key and t.v = p_version and t.l = p_locale
$$;
revoke all on function public.catalog_privacy_notice_hash(text, integer, text) from public, anon, authenticated;

